<style>
@font-face{font-family:'Google Sans';font-style:normal;font-weight:500;font-display:swap;src:url('/auth-assets/google-sans-latin.woff2') format('woff2')}
*{box-sizing:border-box}body{font:1rem/1.5 system-ui,sans-serif;background:#faf6f2;color:#202020;margin:0;padding:16px}main{max-width:440px;margin:3vh auto;background:white;padding:24px;border-radius:20px}h1{font-size:1.6rem;margin-top:0}h2{font-size:1.2rem}label,input,button{display:block;width:100%}input,button{font:inherit;padding:12px;border:1px solid #999;border-radius:10px;margin:8px 0 16px;min-height:48px;min-width:0}button{background:#a8310b;color:white;border:0;cursor:pointer}button:disabled{background:#eee;color:#555;cursor:default}a{color:#a8310b}small{display:block}p[role=alert]{padding:12px;background:#fff1df;border-left:4px solid #a8310b}hr{border:0;border-top:1px solid #ddd;margin:24px 0}:focus-visible{outline:3px solid #265fa4;outline-offset:3px}
.account-modes{display:grid;grid-template-columns:1fr 1fr;gap:8px;margin:20px 0}.account-modes a{display:flex;align-items:center;justify-content:center;min-height:48px;padding:10px 6px;text-align:center;border:1px solid #a8310b;border-radius:10px;text-decoration:none;font-weight:600}.account-modes a[aria-current=page]{background:#a8310b;color:#fff}
.provider{display:flex;align-items:center;gap:12px;border-radius:8px;margin:12px 0;min-height:48px}.provider span:last-child{flex:1;text-align:center}.provider:disabled{opacity:.55;cursor:not-allowed}.provider-google,.provider-google:disabled{background:#fff;color:#1f1f1f;border:1px solid #747775;font:500 .875rem/1.4 'Google Sans',Arial,sans-serif}.provider-apple,.provider-apple:disabled{background:#000;color:#fff;font-weight:500}.provider-mark{display:block;flex:0 0 20px;width:20px;height:20px;overflow:hidden;position:relative}.provider-mark img{display:block;position:absolute;max-width:none}.provider-google img{width:40px;height:40px;left:-10px;top:-10px}.provider-apple{padding:0 12px 0 0;gap:0}.provider-apple .provider-mark{flex-basis:44px;width:44px;height:44px}.provider-apple img{width:44px;height:44px;left:0;top:0}.provider-note{font-size:.875rem;color:#555}summary{cursor:pointer;min-height:44px;padding:10px 0}
</style>
<style>.consent{display:flex;align-items:flex-start;gap:10px;margin:12px 0;font-size:.9rem;min-height:44px}.consent input{flex:0 0 20px;width:20px;min-height:20px;margin:2px 0;padding:0}.consent span{min-width:0}</style>
